sourcesContent:
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';

import './Prediction.css';
import backgroundImage from '../assets/background.jpg';
import sunIcon from '../assets/sun.png';
import moonIcon from '../assets/moon.png';
import sendIcon from '../assets/send.png';

const translations = {
  en: {
    languageLabel: 'Language:',
    yes: 'yes',
    no: 'no',
    startOver: 'Start Over',
    home: '🏠 Home',
    visualization: '📊 Visualization',
    darkModeOn: 'Dark Mode',
    darkModeOff: 'Light Mode',
    typing: 'Typing...',
    questions: [
      "How old are you?",
      "What is your gender?",
      "What's your BMI (Body Mass Index)?",
      "What's your HbA1c Level (%)?",
      "What's your Blood Glucose Level (mg/dL)?",
      "Do you have hypertension?",
      "Do you have heart disease?",
      "What is your smoking history?"
    ],
    genderOptions: ['Female', 'Male', 'Other'],
    smokingOptions: ['never', 'former', 'current', 'not current', 'ever'],
    generalAdviceTitle: "🌟 General Tips:",
    generalAdvice: [
      '🩺 Monitor your blood sugar levels regularly.',
      '⚖️ Maintain a healthy weight.',
      '🏃 Stay physically active (at least 150 minutes/week).',
      '📅 Get regular check-ups with your doctor.',
    ],
    dietAdviceTitle: "🍎 Dietary Advice:",
    dietAdvice: [
      '🥦 Eat plenty of non-starchy vegetables.',
      '🌾 Choose whole grains over refined ones.',
      '🥤 Limit sugary drinks and juices.',
      '🥑 Include healthy fats like avocados and nuts.',
    ],
    warningSignsTitle: "⚠️ Watch for these warning signs:",
    warningSigns: [
      '🚽 Frequent urination.',
      '😰 Excessive thirst.',
      '📉 Unexplained weight loss.',
      '😴 Fatigue and blurred vision.',
    ],
    startMessage1: "Hi there! 👋 I'm your Diabetes Risk Assistant.",
    startMessage2: "Let's get started!",
    thankYou: "Thank you for your answers. Calculating your risk...",
    riskResult: (risk) => `Your predicted diabetes risk is: ${risk}`,
    fallbackRisk: (risk) => `Based on your inputs, your estimated risk is: ${risk}%`,
    adviceQuestion: "Would you like some advice on how to reduce diabetes risk?",
    adviceYesNo: ['yes', 'no'],
    pleaseYesNo: "Please answer 'yes' or 'no'.",
    pleaseChoose: (opts) => `Please choose one of: ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `Please enter a number between ${min} and ${max}`,
    alrightAdviceDeclined: "Alright, feel free to come back anytime if you need advice.",
    okayMoreAdvice: "Okay, feel free to ask for more advice anytime!",
    allAdviceDone: "That's all the advice for now. Stay healthy! 💙",
    consultDoctor: "Remember to consult with your doctor for personalized advice.",
  },
  fr: {
    languageLabel: 'Langue :',
    yes: 'oui',
    no: 'non',
    startOver: 'Recommencer',
    home: '🏠 Accueil',
    visualization: '📊 Visualisation',
    darkModeOn: 'Mode Sombre',
    darkModeOff: 'Mode Clair',
    typing: 'En train d\'écrire...',
    questions: [
      "Quel âge avez-vous ?",
      "Quel est votre genre ?",
      "Quel est votre IMC (Indice de Masse Corporelle) ?",
      "Quel est votre taux d'HbA1c (%) ?",
      "Quel est votre taux de glucose sanguin (mg/dL) ?",
      "Avez-vous de l'hypertension ?",
      "Avez-vous une maladie cardiaque ?",
      "Quel est votre historique tabagique ?"
    ],
    genderOptions: ['Femme', 'Homme', 'Autre'],
    smokingOptions: ['jamais', 'ancien', 'actuel', 'pas actuel', 'déjà fumé'],
    generalAdviceTitle: "🌟 Conseils généraux :",
    generalAdvice: [
      '🩺 Surveillez régulièrement votre glycémie.',
      '⚖️ Maintenez un poids sain.',
      '🏃 Restez physiquement actif (au moins 150 minutes/semaine).',
      '📅 Faites des contrôles réguliers chez votre médecin.',
    ],
    dietAdviceTitle: "🍎 Conseils diététiques :",
    dietAdvice: [
      '🥦 Mangez beaucoup de légumes non féculents.',
      '🌾 Choisissez des grains entiers plutôt que raffinés.',
      '🥤 Limitez les boissons sucrées et les jus.',
      '🥑 Incluez des graisses saines comme les avocats et les noix.',
    ],
    warningSignsTitle: "⚠️ Surveillez ces signes d'alerte :",
    warningSigns: [
      '🚽 Mictions fréquentes.',
      '😰 Soif excessive.',
      '📉 Perte de poids inexpliquée.',
      '😴 Fatigue et vision floue.',
    ],
    startMessage1: "Bonjour ! 👋 Je suis votre assistant pour le risque de diabète.",
    startMessage2: "Commençons !",
    thankYou: "Merci pour vos réponses. Calcul du risque...",
    riskResult: (risk) => `Votre risque de diabète prédit est : ${risk}`,
    fallbackRisk: (risk) => `Selon vos données, votre risque estimé est : ${risk}%`,
    adviceQuestion: "Souhaitez-vous des conseils pour réduire le risque de diabète ?",
    adviceYesNo: ['oui', 'non'],
    pleaseYesNo: "Veuillez répondre par 'oui' ou 'non'.",
    pleaseChoose: (opts) => `Veuillez choisir parmi : ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `Veuillez entrer un nombre entre ${min} et ${max}`,
    alrightAdviceDeclined: "D'accord, revenez quand vous voulez pour des conseils.",
    okayMoreAdvice: "D'accord, n'hésitez pas à demander plus de conseils !",
    allAdviceDone: "Voilà tous les conseils pour le moment. Restez en bonne santé ! 💙",
    consultDoctor: "N'oubliez pas de consulter votre médecin pour des conseils personnalisés.",
  },
  ar: {
    languageLabel: 'اللغة:',
    yes: 'نعم',
    no: 'لا',
    startOver: 'ابدأ من جديد',
    home: '🏠 الصفحة الرئيسية',
    visualization: '📊 التمثيل البياني',
    darkModeOn: 'الوضع الداكن',
    darkModeOff: 'الوضع الفاتح',
    typing: '...يكتب',
    questions: [
      "كم عمرك؟",
      "ما هو جنسك؟",
      "ما هو مؤشر كتلة الجسم (BMI) الخاص بك؟",
      "ما هو مستوى HbA1c (%) الخاص بك؟",
      "ما هو مستوى جلوكوز الدم (mg/dL) الخاص بك؟",
      "هل تعاني من ارتفاع ضغط الدم؟",
      "هل تعاني من أمراض القلب؟",
      "ما هو تاريخ تدخينك؟"
    ],
    genderOptions: ['أنثى', 'ذكر', 'آخر'],
    smokingOptions: ['أبدا', 'سابق', 'حالي', 'ليس حاليا', 'سبق'],
    generalAdviceTitle: "🌟 نصائح عامة:",
    generalAdvice: [
      '🩺 راقب مستويات السكر في الدم بانتظام.',
      '⚖️ حافظ على وزن صحي.',
      '🏃 كن نشيطاً بدنيا (150 دقيقة على الأقل في الأسبوع).',
      '📅 قم بالفحوصات الدورية مع طبيبك.',
    ],
    dietAdviceTitle: "🍎 نصائح غذائية:",
    dietAdvice: [
      '🥦 تناول الكثير من الخضروات غير النشوية.',
      '🌾 اختر الحبوب الكاملة بدلاً من المكررة.',
      '🥤 قلل من المشروبات والعصائر المحلاة.',
      '🥑 أدرج الدهون الصحية مثل الأفوكادو والمكسرات.',
    ],
    warningSignsTitle: "⚠️ راقب علامات التحذير التالية:",
    warningSigns: [
      '🚽 كثرة التبول.',
      '😰 العطش المفرط.',
      '📉 فقدان الوزن غير المبرر.',
      '😴 التعب وتشوش الرؤية.',
    ],
    startMessage1: "مرحباً! 👋 أنا مساعدك في تقييم خطر الإصابة بالسكري.",
    startMessage2: "لنبدأ!",
    thankYou: "شكراً لإجاباتك. جارٍ حساب الخطر...",
    riskResult: (risk) => `مخاطر الإصابة بالسكري المتوقعة لديك هي: ${risk}`,
    fallbackRisk: (risk) => `بناءً على مدخلاتك، تقدير الخطر هو: ${risk}%`,
    adviceQuestion: "هل ترغب في بعض النصائح لتقليل خطر الإصابة بالسكري؟",
    adviceYesNo: ['نعم', 'لا'],
    pleaseYesNo: "يرجى الإجابة بـ 'نعم' أو 'لا'.",
    pleaseChoose: (opts) => `يرجى اختيار واحدة من: ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `يرجى إدخال رقم بين ${min} و ${max}`,
    alrightAdviceDeclined: "حسناً، يمكنك العودة في أي وقت لطلب النصائح.",
    okayMoreAdvice: "حسناً، لا تتردد في طلب المزيد من النصائح في أي وقت!",
    allAdviceDone: "هذا كل النصائح الآن. حافظ على صحتك! 💙",
    consultDoctor: "تذكر استشارة طبيبك للنصائح الشخصية.",
  }
};

const adviceTexts = [
  {
    titleKey: 'generalAdviceTitle',
    adviceKey: 'generalAdvice'
  },
  {
    titleKey: 'dietAdviceTitle',
    adviceKey: 'dietAdvice'
  },
  {
    titleKey: 'warningSignsTitle',
    adviceKey: 'warningSigns'
  }
];

const Prediction = ({ darkMode, setDarkMode }) => {
  const [language, setLanguage] = useState('en');
  const t = translations[language];

  const navigate = useNavigate();

  const [messages, setMessages] = useState([]);
  const [inputValue, setInputValue] = useState('');
  const [currentStep, setCurrentStep] = useState(-2); // -2: intro1, -1: intro2, then 0..7 questions, 8: advice prompt, 9+ advice
  const [isTyping, setIsTyping] = useState(false);
  const [showOptions, setShowOptions] = useState([]);
  const [adviceStep, setAdviceStep] = useState(0);
  const [awaitingYesNo, setAwaitingYesNo] = useState(false);
  const [risk, setRisk] = useState(null);

  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages]);

  useEffect(() => {
    resetChat();
  }, [language]);

  // Questions config
  const questions = [
    { 
      question: t.questions[0], 
      type: 'number', min: 0, max: 120 
    },
    { 
      question: t.questions[1], 
      type: 'options', 
      options: t.genderOptions 
    },
    { 
      question: t.questions[2], 
      type: 'number', min: 10, max: 50 
    },
    { 
      question: t.questions[3], 
      type: 'number', min: 3, max: 15 
    },
    { 
      question: t.questions[4], 
      type: 'number', min: 40, max: 500 
    },
    { 
      question: t.questions[5], 
      type: 'boolean' 
    },
    { 
      question: t.questions[6], 
      type: 'boolean' 
    },
    { 
      question: t.questions[7], 
      type: 'options', 
      options: t.smokingOptions 
    }
  ];

  const resetChat = () => {
    setMessages([
      { sender: 'bot', text: t.startMessage1 },
    ]);
    setCurrentStep(-2);
    setInputValue('');
    setShowOptions([]);
    setIsTyping(false);
    setAdviceStep(0);
    setAwaitingYesNo(false);
    setRisk(null);

    // Second intro message after 2 seconds
    setTimeout(() => {
      addBotMessage(t.startMessage2);
      setTimeout(() => {
        askQuestion(0);
        setCurrentStep(0);
      }, 1000);
    }, 2000);
  };

  const addBotMessage = (text, options = []) => {
    setMessages(prev => [...prev, { sender: 'bot', text, options }]);
    setShowOptions(options);
  };

  const addUserMessage = (text) => {
    setMessages(prev => [...prev, { sender: 'user', text }]);
    setShowOptions([]);
  };

  const askQuestion = (step) => {
    if (step < questions.length) {
      const q = questions[step];
      addBotMessage(q.question, q.type === 'options' ? q.options : []);
    } else {
      // All questions answered, proceed to calculate risk or advice prompt
      addBotMessage(t.thankYou);
      setIsTyping(true);
      setTimeout(() => {
        setIsTyping(false);
        calculateRisk();
        setTimeout(() => {
          addBotMessage(t.adviceQuestion, t.adviceYesNo);
          setAwaitingYesNo(true);
          setCurrentStep(questions.length);
        }, 1500);
      }, 2000);
    }
  };

  const validateInput = (step, input) => {
    const q = questions[step];
    if (!input || input.trim().length === 0) {
      return "Input cannot be empty.";
    }
    if (q.type === 'number') {
      const val = Number(input);
      if (isNaN(val)) return t.enterNumberBetween(q.min, q.max);
      if (val < q.min || val > q.max) return t.enterNumberBetween(q.min, q.max);
    } else if (q.type === 'options') {
      if (!q.options.includes(input)) return t.pleaseChoose(q.options);
    } else if (q.type === 'boolean') {
      if (![t.yes, t.no].includes(input.toLowerCase())) return t.pleaseYesNo;
    }
    return null;
  };

  const calculateRisk = () => {
    // Simple dummy risk calculation based on answers for demo
    // Find relevant answers:
    let age = Number(getAnswer(0)) || 30;
    let gender = getAnswer(1) || t.genderOptions[0];
    let bmi = Number(getAnswer(2)) || 25;
    let hba1c = Number(getAnswer(3)) || 5.5;
    let glucose = Number(getAnswer(4)) || 100;
    let hypertension = getAnswer(5) === t.yes.toLowerCase();
    let heartDisease = getAnswer(6) === t.yes.toLowerCase();
    let smoking = getAnswer(7) || t.smokingOptions[0];

    let riskCalc = 5; // base risk %

    riskCalc += (age - 30) * 0.2;
    riskCalc += (bmi - 25) * 0.5;
    riskCalc += (hba1c - 5) * 10;
    riskCalc += (glucose - 100) * 0.05;
    if (hypertension) riskCalc += 5;
    if (heartDisease) riskCalc += 5;
    if (smoking === t.smokingOptions[2].toLowerCase()) riskCalc += 7; // current smoker
    if (riskCalc < 0) riskCalc = 0;
    if (riskCalc > 100) riskCalc = 100;

    riskCalc = Math.round(riskCalc * 10) / 10;

    setRisk(riskCalc);
    addBotMessage(t.riskResult(riskCalc));
  };

  const getAnswer = (index) => {
    const msg = messages.find((m, idx) => idx === index * 2 + 1); // user messages at odd indices (0 bot,1 user,2 bot,3 user...)
    return msg?.text?.toLowerCase() || null;
  };

  const handleSubmit = () => {
    if (!inputValue.trim()) return;
    const userInputRaw = inputValue.trim();

    // For Arabic yes/no, convert to lowercase and normalize for boolean check
    const userInput = userInputRaw.toLowerCase();

    if (awaitingYesNo) {
      if ([t.yes, t.no].includes(userInput)) {
        addUserMessage(userInputRaw);
        setInputValue('');
        setAwaitingYesNo(false);
        if (userInput === t.yes) {
          setCurrentStep(currentStep + 1);
          setTimeout(() => {
            showAdvice(adviceStep);
          }, 1000);
        } else {
          addBotMessage(t.alrightAdviceDeclined);
          setCurrentStep(currentStep + 10);
        }
      } else {
        addBotMessage(t.pleaseYesNo);
      }
      return;
    }

    if (currentStep < questions.length) {
      const error = validateInput(currentStep, userInputRaw);
      if (error) {
        addBotMessage(error);
        setInputValue('');
        return;
      }
      addUserMessage(userInputRaw);
      setInputValue('');
      setIsTyping(true);
      setTimeout(() => {
        setIsTyping(false);
        setCurrentStep(currentStep + 1);
        askQuestion(currentStep + 1);
      }, 1500);
    } else if (currentStep >= questions.length) {
      // Advice steps handling
      if (currentStep >= questions.length && currentStep < questions.length + adviceTexts.length) {
        // Expect yes/no
        if ([t.yes, t.no].includes(userInput)) {
          addUserMessage(userInputRaw);
          setInputValue('');
          if (userInput === t.yes) {
            showAdvice(adviceStep);
          } else {
            addBotMessage(t.okayMoreAdvice);
            setCurrentStep(questions.length + adviceTexts.length + 1);
          }
        } else {
          addBotMessage(t.pleaseYesNo);
        }
      } else {
        // No more advice, can reset or ignore
        addBotMessage(t.allAdviceDone);
      }
    }
  };

  const showAdvice = (step) => {
    if (step >= adviceTexts.length) {
      addBotMessage(t.allAdviceDone + "\n" + t.consultDoctor);
      setCurrentStep(currentStep + 10);
      return;
    }
    const adviceSet = adviceTexts[step];
    addBotMessage(t[adviceSet.titleKey]);
    adviceSet.adviceKey && t[adviceSet.adviceKey].forEach((advice, i) => {
      setTimeout(() => {
        addBotMessage(advice);
      }, 1000 * (i + 1));
    });
    setAdviceStep(step + 1);
    setCurrentStep(currentStep + 1);
  };

  const toggleDarkMode = () => {
    setDarkMode(!darkMode);
  };

  const handleLanguageChange = (e) => {
    setLanguage(e.target.value);
  };

  const onKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleSubmit();
    }
  };

  return (
    <div
      className={`prediction-page ${darkMode ? 'dark' : 'light'}`}
      style={{ backgroundImage: `url(${backgroundImage})` }}
      dir={language === 'ar' ? 'rtl' : 'ltr'}
    >
      <header className="header">
        <nav className="nav-buttons">
          <button onClick={() => navigate('/')} title={t.home}>{t.home}</button>
          <button onClick={() => navigate('/visualization')} title={t.visualization}>{t.visualization}</button>
          <button onClick={resetChat} title={t.startOver}>{t.startOver}</button>
        </nav>
        <div className="language-toggle">
          <label htmlFor="language-select">{t.languageLabel}</label>
          <select id="language-select" value={language} onChange={handleLanguageChange}>
            <option value="en">English</option>
            <option value="fr">Français</option>
            <option value="ar">العربية</option>
          </select>
        </div>
        <button
          className="darkmode-toggle"
          onClick={toggleDarkMode}
          title={darkMode ? t.darkModeOn : t.darkModeOff}
        >
          <img
            src={darkMode ? sunIcon : moonIcon}
            alt={darkMode ? t.darkModeOn : t.darkModeOff}
            className="darkmode-icon"
          />
        </button>
      </header>

      <main className="chat-container">
        <div className="messages">
          {messages.map((msg, idx) => (
            <div
              key={idx}
              className={`message ${msg.sender === 'bot' ? 'bot-message' : 'user-message'}`}
            >
              {msg.text}
              {msg.options && msg.options.length > 0 && (
                <div className="options-container">
                  {msg.options.map((opt, i) => (
                    <button
                      key={i}
                      onClick={() => {
                        setInputValue(opt);
                        handleSubmit();
                      }}
                      className="option-button"
                    >
                      {opt}
                    </button>
                  ))}
                </div>
              )}
            </div>
          ))}
          {isTyping && (
            <div className="message bot-message typing-indicator">
              {t.typing}
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        <div className="input-container">
          <input
            type="text"
            placeholder={currentStep < questions.length ? t.questions[currentStep] : ''}
            value={inputValue}
            onChange={e => setInputValue(e.target.value)}
            onKeyDown={onKeyDown}
            aria-label="Chat input"
            autoComplete="off"
          />
          <button onClick={handleSubmit} aria-label="Send message">{t.send}</button>
        </div>
      </main>
    </div>
  );
};

export default Prediction;
